def flow(steps, end, link=False):
    s='<div class="flow">'
    for i,t in enumerate(steps): s+=f'<div class="fstep reveal"><span class="n">{i+1}</span>{md(t)}</div><i class="farr">➜</i>'
    return s+f'<div class="fstep end">🌅 {md(end)}</div></div>'
def tbl(head, rows, cls=""):
    return f'<div class="tbl"><table class="{cls}"><thead><tr>'+"".join(f'<th>{h}</th>' for h in head)+'</tr></thead><tbody>'+"".join('<tr>'+"".join(f'<td>{md(c) if isinstance(c,str) else c}</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table></div>'
